const operationName = $json.name ?? $json.body?.name ?? $json.data?.name;

if (!operationName) {
  throw new Error(`No operation name returned. Keys: ${Object.keys($json).join(', ')}`);
}

return {
  json: {
    operationName,
    dreamId: $('Set Inputs').first().json.dreamId,
    summary: $('Set Inputs').first().json.summary,
  },
};

const raw = $json.body ?? $json;
const done = Boolean(raw.done ?? false);

// If done=true but API returned an error (e.g. RESOURCE_EXHAUSTED code 8)
const apiError = raw.error ?? null;
const apiErrorMessage = apiError?.message ?? null;

const response = raw.response ?? {};

const videosList =
  response.videos ??
  response.generatedSamples ??
  response.generateVideoResponse?.generatedSamples ??
  [];

const gcsUri =
  videosList[0]?.gcsUri ??
  videosList[0]?.video?.uri ??
  videosList[0]?.uri ??
  null;

const operationName =
  raw.operationName ??
  raw.name ??
  $('Normalize Operation').first().json.operationName;

return {
  json: {
    done,
    apiError: apiErrorMessage,
    videos: videosList,
    gcsUri,
    operationName,
    dreamId: $('Normalize Operation').first().json.dreamId,
    summary: $('Normalize Operation').first().json.summary,
  },
};

