const data = $input.first().json;

const dreamId =
  data.dreamId ||
  $('Set Inputs').item.json.dreamId ||
  $('Prepare Video Input').item.json.dreamId ||
  null;

const summary =
  data.summary ||
  $('Set Inputs').item.json.summary ||
  $('Prepare Video Input').item.json.summary ||
  null;

const operationName =
  data.operationName ||
  data.name ||
  $('Set Inputs').item.json.operationName ||
  null;

if (!dreamId) {
  throw new Error('dreamId manquant : impossible de sauvegarder la vidéo.');
}

// Veo API returned an error (ex: RESOURCE_EXHAUSTED code 8)
if (data.apiError) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:3000/api/dreams-video-callback',
    headers: {
      Authorization: 'Bearer 8f4d9c2a7b1e5m3q9x6k2p7z1h4r8t0',
      'Content-Type': 'application/json',
    },
    body: { dreamId, status: 'failed', errorMessage: data.apiError },
    json: true,
  });
  return [{ json: { saved: false, dreamId, status: 'failed', error: data.apiError } }];
}

const gcsUri =
  data.gcsUri ||
  data.videos?.[0]?.gcsUri ||
  data.videos?.[0]?.video?.uri ||
  data.videos?.[0]?.uri ||
  null;

if (!gcsUri) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:3000/api/dreams-video-callback',
    headers: {
      Authorization: 'Bearer 8f4d9c2a7b1e5m3q9x6k2p7z1h4r8t0',
      'Content-Type': 'application/json',
    },
    body: { dreamId, status: 'failed', errorMessage: 'No gcsUri found' },
    json: true,
  });
  return [{ json: { saved: false, dreamId, status: 'failed', error: 'No gcsUri found' } }];
}

const videoUrl = gcsUri.replace('gs://', 'https://storage.googleapis.com/');

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://host.docker.internal:3000/api/dreams-video-callback',
  headers: {
    Authorization: 'Bearer 8f4d9c2a7b1e5m3q9x6k2p7z1h4r8t0',
    'Content-Type': 'application/json',
  },
  body: { dreamId, summary, videoUrl, gcsUri, operationName, status: 'ready' },
  json: true,
});

return [{ json: { saved: true, dreamId, videoUrl, gcsUri, operationName, status: 'ready', callbackResponse: response } }];

const originalDream = String($json.original_dream || "");
const dreamAnalysis = String($json.dream_analysis || "");

const sentences = originalDream
  .split(/[.!?\n]+/)
  .map(s => s.trim())
  .filter(s => s.length > 0);

const sentenceCount = sentences.length;
const routeResume = "resume";

return [
  {
    json: {
      ...$json,
      locale: $json.locale || $('Extraction Texte Rêve').first().json.locale || 'fr',
      original_dream: originalDream,
      dream_analysis: dreamAnalysis,
      sentence_count: sentenceCount,
      route_resume: routeResume,
      output: ""
    }
  }
];

