const rawOutput = $json.output || "{}";

const cleanedOutput = rawOutput
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleanedOutput);
} catch (error) {
  parsed = {
    route_analyse: "simple",
    stress_detected: false,
    emotion_principale: "neutre",
    raison_classification: "Erreur de lecture de la sortie de l'agent."
  };
}

const locale = $('Extraction Texte Rêve').item.json.locale || 'fr';

const routeAnalyse = String(parsed.route_analyse || "simple")
  .trim()
  .toLowerCase();

const isComplexe = routeAnalyse === "complexe";

return [
  {
    json: {
      ...$json,
      locale,
      route_analyse: routeAnalyse,
      is_complexe: isComplexe,
      stress_detected: parsed.stress_detected === true,
      emotion_principale: parsed.emotion_principale || "neutre",
      raison_classification: parsed.raison_classification || ""
    }
  }
];

const locale = $('Extraction Texte Rêve').item.json.locale || 'fr';
const otherLocale = locale === 'en' ? 'fr' : 'en';
const summary = $json.output || '';
const analysis = $('Code in JavaScript').item.json.dream_analysis || '';
const description = $('Extraction Texte Rêve').item.json.dream || '';
const targetLang = otherLocale === 'en' ? 'English' : 'French';
const sourceLang = locale === 'en' ? 'English' : 'French';

return [{ json: { locale, otherLocale, summary, analysis, description, sourceLang, targetLang } }];

