parameters.jsCode:
const raw = $json.output || '{}';
// Try to extract JSON even if wrapped in markdown
const match = raw.match(/\{[\s\S]*\}/);
const cleaned = match ? match[0] : '{}';
let parsed = {};
try { parsed = JSON.parse(cleaned); } catch {}

const inp = $('Set Translation Input').item.json;

return [{ json: {
  locale: inp.locale,
  otherLocale: inp.otherLocale,
  description_primary: inp.description,
  summary_primary: inp.summary,
  analysis_primary: inp.analysis,
  description_other: (parsed.d || '').trim() || inp.description,
  summary_other: (parsed.s || '').trim() || inp.summary,
  analysis_other: (parsed.a || '').trim() || inp.analysis
} }];
